import sys

def main():
    lines = sys.stdin.read().split('\n')
    n, m = map(int, lines[0].split())
    free = set()
    for i in range(n):
        row = lines[1 + i].strip()
        for j in range(m):
            if row[j] == '.':
                free.add((i, j))
    parts = lines[1 + n].split()
    pos = (int(parts[0]), int(parts[1]))
    vectors = {'N': (-1, 0), 'E': (0, 1), 'S': (1, 0), 'W': (0, -1)}
    names = {v: k for k, v in vectors.items()}
    vec = vectors[parts[2]]
    cmds = lines[3 + n].strip()
    for ch in cmds:
        if ch == 'R':
            vec = (vec[1], -vec[0])
        elif ch == 'L':
            vec = (-vec[1], vec[0])
        else:
            nxt = (pos[0] + vec[0], pos[1] + vec[1])
            if nxt in free:
                pos = nxt
    print(pos[0], pos[1], names[vec])

main()
